D="deploy/clickstream-etl -n analytics"
check "2 replicas ready, all on $MAIN_W2" bash -c "deploy_ready main clickstream-etl analytics 2 &&
  [ \"\$(kubectl --context main -n analytics get pods -l \"\$(kubectl --context main -n analytics get deploy clickstream-etl -o jsonpath='{.spec.selector.matchLabels}' | tr -d '{}\"' | tr : =)\" --field-selector=status.phase=Running -o jsonpath='{range .items[*]}{.spec.nodeName}{\"\\n\"}{end}' | sort -u)\" = $MAIN_W2 ]"
check "required node affinity on workload=analytics" bash -c "kubectl --context main -n analytics get deploy clickstream-etl -o jsonpath='{.spec.template.spec.affinity.nodeAffinity.requiredDuringSchedulingIgnoredDuringExecution.nodeSelectorTerms}' | grep -q '\"key\":\"workload\"' && kubectl --context main -n analytics get deploy clickstream-etl -o jsonpath='{.spec.template.spec.affinity.nodeAffinity.requiredDuringSchedulingIgnoredDuringExecution.nodeSelectorTerms}' | grep -q analytics"
check "toleration for dedicated=analytics:NoSchedule" field_has main "$D" '{.spec.template.spec.tolerations[?(@.key=="dedicated")].effect}' NoSchedule
check "requests 100m/64Mi, memory limit 128Mi" bash -c "[ \"\$(kubectl --context main -n analytics get deploy clickstream-etl -o jsonpath='{.spec.template.spec.containers[0].resources.requests.cpu}/{.spec.template.spec.containers[0].resources.requests.memory}/{.spec.template.spec.containers[0].resources.limits.memory}')\" = 100m/64Mi/128Mi ]"
